Fixpoint ox2 (jt : list byte) (cells : list (option deltX2)) : list byte :=
  match cells, jt with
  | o :: cs, b0 :: b1 :: b2 :: b3 :: jt' =>
      match o with
      | Some c => Z_to_bv 8 (x2_seq c) :: Z_to_bv 8 (x2_seq c / 256) :: Z_to_bv 8 (x2_nbBits c) :: Z_to_bv 8 (x2_len c)
                    :: ox2 jt' cs
      | None => b0 :: b1 :: b2 :: b3 :: ox2 jt' cs
      end
  | _, _ => jt
  end.

