Lemma upd_bytes_cons4 : forall (b0 b1 b2 b3 : byte) l k bs,
  upd_bytes (b0 :: b1 :: b2 :: b3 :: l) (4 + k) bs = b0 :: b1 :: b2 :: b3 :: upd_bytes l k bs.
Proof.
