Lemma ox2_store : forall cells jt u c, (u < length cells)%nat -> length jt = (4 * length cells)%nat ->
  upd_bytes (upd_bytes (ox2 jt cells) (4 * u) [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256)]) (4 * u + 2)
            [Z_to_bv 8 (x2_nbBits c); Z_to_bv 8 (x2_len c)]
