Lemma nth_upd_bytes : forall (l bs : list byte) k n d, (k + length bs <= length l)%nat ->
  nth n (upd_bytes l k bs) d = if (k <=? n)%nat && (n <? k + length bs)%nat then nth (n - k) bs d else nth n l d.
Proof.
