Lemma upd_bytes_comm2 : forall (l : list byte) i j xs ys, length xs = 2%nat -> length ys = 2%nat -> (i + 2 <= j)%nat ->
  (j + 2 <= length l)%nat ->
  upd_bytes (upd_bytes l j ys) i xs = upd_bytes (upd_bytes l i xs) j ys.
