Lemma ffw_step : forall f dt base b e nb tl bs lvl sorted, b <> e ->
  fill_for_weight (S f) dt base b e nb tl bs lvl sorted =
    let! length := shl32 1 (Z.land (tl - nb) 31) in
    let! sym := oload sorted b in
    let! dt' := store_run (Z.to_nat length) dt base (build_x2 sym nb bs lvl) in
    fill_for_weight f dt' (base + length) (b + 1) e nb tl bs lvl sorted.
