Lemma l2w_step : forall f dt base w mw1 tl cons rv sorted rs0 nbb bseq, w < mw1 ->
  level2_weights (S f) dt base w mw1 tl cons rv sorted rs0 nbb bseq =
    let! b := load rs0 w in
    let! e := load rs0 (w + 1) in
    let! off := load rv (rv_idx cons w) in
    let! r := fill_for_weight (S (Z.to_nat (e - b))) dt (base + off) b e (nbb - w + cons) tl bseq 2 sorted in
    let '(dt', _) := r in
    level2_weights f dt' base (w + 1) mw1 tl cons rv sorted rs0 nbb bseq.
Proof.
