Lemma fx2_step : forall f dt w wEnd tl rv sorted rs0 nbb, w < wEnd ->
  fill_x2 (S f) dt w wEnd tl rv sorted rs0 nbb =
    let! b := load rs0 w in
    let! e := load rs0 (w + 1) in
    let! dt' :=
      (if nbb - (wEnd - 1) <=? tl - (nbb - w) then
         let! start := load rv (rv_idx 0 w) in
         let! length := shl32 1 (Z.land (tl - (nbb - w)) 31) in
         fill_two_level (S (Z.to_nat (e - b))) dt b e start length tl (nbb - w) (Z.max 1 (nbb - w + (nbb - tl))) wEnd rv
           sorted rs0 nbb
       else
         let! start := load rv (rv_idx 0 w) in
         let! r := fill_for_weight (S (Z.to_nat (e - b))) dt start b e (nbb - w) tl 0 1 sorted in
         let '(dt1, _) := r in Ok dt1) in
    fill_x2 f dt' (w + 1) wEnd tl rv sorted rs0 nbb.
Proof.
