Lemma ffw_ok : forall f dt base b e nb tl bs lvl sorted r, fill_for_weight f dt base b e nb tl bs lvl sorted = Ok r ->
  Z.of_nat f = e - b + 1 -> b <= e -> 0 <= tl - nb < 32 -> 0 <= base ->
  snd r = base + (e - b) * 2 ^ (tl - nb) /\ length (fst r) = length dt.
Proof.
