Definition rv_at (m : fmem) (WK : Z) (rv : list Z) (P : Z -> Prop) : Prop :=
  exists rvw : list word, length rvw = 156%nat /\ u32arr usegs m WK rvw /\
    forall i, P i -> 0 <= i < 156 -> nth (Z.to_nat i) rvw (Z_to_bv 64 0) = Z_to_bv 64 (Znth i rv).

